const row = $input.first().json || {};
const body = row.body && typeof row.body === 'object' ? row.body : row;
function normalizeShotToken(v) {
  const raw = String(v || '').trim();
  if (!raw) return '';
  if (/^shot[_-]?\d+$/i.test(raw)) {
    const num = raw.match(/(\d+)/)?.[1] || '';
    return num ? 'shot_' + num : raw;
  }
  if (/^\d+$/.test(raw)) return 'shot_' + raw;
  return raw;
}
const normalizedBadShotIds = String(body.bad_shot_ids ?? body['需重做镜头编号'] ?? '')
  .split(/[\n,，\s]+/)
  .map(normalizeShotToken)
  .filter(Boolean);
return [{
  json: {
    ...body,
    review_decision: body.review_decision ?? body['确认结论'] ?? body.decision ?? '',
    bad_shot_ids: normalizedBadShotIds.join(','),
    bad_shot_ids_list: normalizedBadShotIds,
    review_feedback: body.review_feedback ?? body['修改意见'] ?? '',
    review_round_hidden: body.review_round_hidden ?? body.review_round ?? 1,
