    project_id: body.project_id || '',
    product_name: body.product_name || '',
    rerun_failed_only: body.rerun_failed_only === true || String(body.rerun_failed_only || '').trim() === '1',
  },
}];

const process = require('process');
const PROJECT_ROOT = process.env.TIKTOK_WORKFLOW_ROOT || process.env.PROJECT_ROOT || process.cwd();
const DATA_ROOT = require('process').env.WORKFLOW_DATA_ROOT || require('path').join(require('os').homedir(), 'Library', 'Application Support', 'AI Video', 'workflow-data') || require('process').env.AI_VIDEO_RUNTIME_ROOT || PROJECT_ROOT;
const fs = require('fs');
const path = require('path');

const row = $input.first().json || {};

function normalizeDecision(v) {
  const s = String(v || '').trim().toLowerCase();
  if (!s) return true;
  if (s.includes('重做') || s.includes('redo') || s.includes('reject') || s.includes('revise')) return false;
  if (s.includes('通过') || s.includes('approve') || s.includes('pass') || s === 'ok' || s === 'yes' || s === 'y') return true;
  return true;
}

function normalizeShotToken(v) {
  const raw = String(v || '').trim();
  if (!raw) return '';
  if (/^shot[_-]?\d+$/i.test(raw)) {
    const num = raw.match(/(\d+)/)?.[1] || '';
    return num ? 'shot_' + num : raw;
  }
  if (/^\d+$/.test(raw)) return 'shot_' + raw;
  return raw;
}
function normalizeReviewContextPath(contextPath) {
  let normalized = String(contextPath || '').trim();
  while (normalized.endsWith('.submitted.json')) {
    normalized = normalized.slice(0, -'.submitted.json'.length);
  }
  return normalized;
}


const rerunFailedOnly = !!row.rerun_failed_only;
const rerunPendingOnly = !!row.rerun_pending_only;
const decisionValue = row.review_decision ?? row['确认结论'] ?? row.decision ?? '';
const approved = rerunFailedOnly ? true : normalizeDecision(decisionValue);
const badShotIds = String(row.bad_shot_ids ?? row['需重做镜头编号'] ?? '')
  .split(/[\n,，\s]+/)
  .map(normalizeShotToken)
  .filter(Boolean);
const feedback = String(row.review_feedback ?? row['修改意见'] ?? '').trim();
const currentRound = Number(row.review_round || row['review_round_hidden'] || 1);
const reviewContextPath = normalizeReviewContextPath(row.review_context_path || row['review_context_path_hidden'] || '');
let reviewContext = {};

if (reviewContextPath) {
  if (!fs.existsSync(reviewContextPath)) {
    throw new Error('解析用户确认：确认上下文文件不存在 ' + reviewContextPath);
  }
  try {
    reviewContext = JSON.parse(fs.readFileSync(reviewContextPath, 'utf8'));
  } catch (e) {
    throw new Error('解析用户确认：确认上下文文件不是合法 JSON，详情：' + e.message);
  }
}

let panels = Array.isArray(reviewContext.panel_review_pack) ? reviewContext.panel_review_pack : [];
const projectId = row.project_id || reviewContext.project_id || '';
const progressPath = projectId
  ? path.join(DATA_ROOT, '.n8n-local-cache', 'review-progress', 'review_progress_' + String(projectId).replace(/[^a-zA-Z0-9_-]+/g, '_') + '.json')
  : '';
let progress = {};
if (progressPath && fs.existsSync(progressPath)) {
  try {
    progress = JSON.parse(fs.readFileSync(progressPath, 'utf8'));
  } catch (e) {}
}

if (rerunFailedOnly) {
  if (badShotIds.length > 0) {
    // Explicit single-shot rerun: select by bad_shot_ids regardless of progress status
    const explicitIdSet = new Set(badShotIds.flatMap(function(s){var n=String(s);return [n, n.replace(/^shot_/,'')];}));
    const explicitOrderSet = new Set(badShotIds.map((s) => String(s).replace(/^shot_/, '')));
    const shotStateMap = new Map(
      (Array.isArray(progress.shots) ? progress.shots : []).map((shot) => [String(shot.shot_id), shot])
    );
    panels = panels
      .filter((panel) => explicitIdSet.has(String(panel.shot_id)) || explicitOrderSet.has(String(panel.shot_order)))
      .map((panel) => {
        const shotState = shotStateMap.get(String(panel.shot_id)) || {};
        return {
          ...panel,
          veo_fail_streak: Number(shotState.veo_fail_streak || panel.veo_fail_streak || 0),
          veo_prompt_regen_count: Number(shotState.veo_prompt_regen_count || panel.veo_prompt_regen_count || 0),
          veo_generation_attempt_total: Number(shotState.veo_generation_attempt_total || panel.veo_generation_attempt_total || 0),
          veo_failure_history: Array.isArray(shotState.veo_failure_history) ? shotState.veo_failure_history : (Array.isArray(panel.veo_failure_history) ? panel.veo_failure_history : []),
        };
      });
    if (!panels.length) {
      throw new Error('只重跑指定镜头：bad_shot_ids 未能在 review_context 中匹配到对应 panel');
    }
  } else {
    // Bulk failed rerun (no explicit shot IDs): unchanged behavior
    const failedShots = Array.isArray(progress.shots)
      ? progress.shots.filter((shot) => String(shot.status || '') === 'failed')
      : [];
    if (!failedShots.length) {
      throw new Error('只重跑失败镜头：当前没有可重跑的失败镜头');
    }
    const failedIdSet = new Set(failedShots.map((shot) => String(shot.shot_id)));
    const failedOrderSet = new Set(failedShots.map((shot) => String(shot.shot_order)));
    const shotStateMap = new Map(failedShots.map((shot) => [String(shot.shot_id), shot]));
    panels = panels
      .filter((panel) => failedIdSet.has(String(panel.shot_id)) || failedOrderSet.has(String(panel.shot_order)))
      .map((panel) => {
        const shotState = shotStateMap.get(String(panel.shot_id)) || {};
        return {
          ...panel,
          veo_fail_streak: Number(shotState.veo_fail_streak || panel.veo_fail_streak || 0),
          veo_prompt_regen_count: Number(shotState.veo_prompt_regen_count || panel.veo_prompt_regen_count || 0),
          veo_generation_attempt_total: Number(shotState.veo_generation_attempt_total || panel.veo_generation_attempt_total || 0),
          veo_failure_history: Array.isArray(shotState.veo_failure_history) ? shotState.veo_failure_history : (Array.isArray(panel.veo_failure_history) ? panel.veo_failure_history : []),
        };
      });
    if (!panels.length) {
      throw new Error('只重跑失败镜头：失败镜头未能在 review_context 中匹配到对应 panel');
    }
  }
}

if (rerunPendingOnly) {
  const pendingShots = Array.isArray(progress.shots)
    ? progress.shots.filter((shot) => String(shot.status || 'pending') === 'pending')
    : [];
  if (!pendingShots.length) {
    throw new Error('继续生成剩余镜头：当前没有待生成镜头');
  }
  const pendingIdSet = new Set(pendingShots.map((shot) => String(shot.shot_id)));
  const pendingOrderSet = new Set(pendingShots.map((shot) => String(shot.shot_order)));
  const shotStateMap = new Map(pendingShots.map((shot) => [String(shot.shot_id), shot]));
  panels = panels
    .filter((panel) => pendingIdSet.has(String(panel.shot_id)) || pendingOrderSet.has(String(panel.shot_order)))
    .map((panel) => {
      const shotState = shotStateMap.get(String(panel.shot_id)) || {};
      return {
        ...panel,
        veo_fail_streak: Number(shotState.veo_fail_streak || panel.veo_fail_streak || 0),
        veo_prompt_regen_count: Number(shotState.veo_prompt_regen_count || panel.veo_prompt_regen_count || 0),
        veo_generation_attempt_total: Number(shotState.veo_generation_attempt_total || panel.veo_generation_attempt_total || 0),
        veo_failure_history: Array.isArray(shotState.veo_failure_history) ? shotState.veo_failure_history : (Array.isArray(panel.veo_failure_history) ? panel.veo_failure_history : []),
      };
    });
  if (!panels.length) {
    throw new Error('继续生成剩余镜头：待生成镜头未能在 review_context 中匹配到对应 panel');
  }
}

return [{
  json: {
    ...reviewContext,
    ...row,
    project_id: projectId,
    product_name: row.product_name || reviewContext.product_name || '',
    panel_review_pack: panels,
    review_context_path: reviewContextPath || normalizeReviewContextPath(reviewContext.review_context_path || '') || '',
    review_approved: approved,
    review_feedback: feedback,
    bad_shot_ids: badShotIds.join(','),
    bad_shot_ids_list: badShotIds,
    review_round: approved ? currentRound : currentRound + 1,
    previous_review_round: currentRound,
    manual_regeneration_requested: !approved,
    rerun_failed_only: rerunFailedOnly,
    rerun_pending_only: rerunPendingOnly,
    review_progress_path: progressPath,
  },
}];

const fs = require('fs');

const row = $input.first().json || {};

function normalizeReviewContextPath(contextPath) {
  let normalized = String(contextPath || '').trim();
  while (normalized.endsWith('.submitted.json')) {
    normalized = normalized.slice(0, -'.submitted.json'.length);
  }
  return normalized;
}

let panels = Array.isArray(row.panel_review_pack) ? row.panel_review_pack : [];
const reviewContextPath = normalizeReviewContextPath(row.review_context_path || row.review_context_path_hidden || '');

if (!panels.length && reviewContextPath && fs.existsSync(reviewContextPath)) {
  try {
    const ctx = JSON.parse(fs.readFileSync(reviewContextPath, 'utf8'));
    if (Array.isArray(ctx.panel_review_pack)) {
      panels = ctx.panel_review_pack;
    }
  } catch (e) {
    throw new Error('恢复已确认分镜：无法读取确认上下文，详情：' + e.message);
  }
}

if (!panels.length) {
  throw new Error('恢复已确认分镜：panel_review_pack 为空');
}


// D-fix: filter shots by status to prevent duplicate Veo submissions
const _rerunPendingOnly = Boolean(row.rerun_pending_only);
const _rerunFailedOnly = Boolean(row.rerun_failed_only);
const _badShotIds = String(row.bad_shot_ids || '').split(',').map(s => s.trim()).filter(Boolean);
const _progressPath = String(row.review_progress_path || '').trim();
const _existingStatuses = {};
if (_progressPath && fs.existsSync(_progressPath)) {
  try {
    const _prog = JSON.parse(fs.readFileSync(_progressPath, 'utf8'));
    for (const _shot of (Array.isArray(_prog.shots) ? _prog.shots : [])) {
      _existingStatuses[String(_shot.shot_id || '')] = String(_shot.status || 'pending').toLowerCase();
    }
  } catch (_e) {}
}
const SKIP_STATUSES = ['completed', 'done', 'submitted', 'running'];


// D-fix: apply shot filter before processing
const _panelsFiltered = _rerunPendingOnly || _rerunFailedOnly
  ? panels.filter(panel => {
      const shotId = String(panel.shot_id || '');
      const status = _existingStatuses[shotId] || _existingStatuses['shot_' + shotId] || 'pending';
      if (_rerunFailedOnly) {
        if (_badShotIds.length > 0) return _badShotIds.includes(shotId) || _badShotIds.includes('shot_' + shotId);
        return status === 'failed';
      }
      return status === 'pending' || !status;
    })
  : panels;

return _panelsFiltered.map((panel) => {
  const imagePath = panel.panel_image_path || '';
  if (!imagePath || !fs.existsSync(imagePath)) {
    throw new Error('恢复已确认分镜失败：本地图片不存在 ' + imagePath);
  }
  const b64 = fs.readFileSync(imagePath).toString('base64');
  const mimeType = panel.panel_mime_type || 'image/jpeg';
  const fileName = panel.panel_file_name || 'panel.jpg';
  return {
    json: {
      ...panel,
      review_round: row.previous_review_round || row.review_round || panel.review_round || 1,
      review_approved: true,
      final_confirmation_status: 'approved',
      project_id: row.project_id || panel.project_id || '',
      product_name: row.product_name || panel.product_name || '',
      target_market: row.target_market || panel.target_market || '',
      target_language: row.target_language || panel.target_language || '',
      creative_task_type: row.creative_task_type || panel.creative_task_type || '',
      selected_concept_id: row.selected_concept_id || panel.selected_concept_id || '',
      review_progress_path: row.review_progress_path || '',
      review_context_path: reviewContextPath || row.review_context_path || '',
      total_panels: Number(row.total_panels || panels.length || 0),
      veo_prompt_original: panel.video_prompt || '',
      veo_fail_streak: Number(panel.veo_fail_streak || 0),
      veo_prompt_regen_count: Number(panel.veo_prompt_regen_count || 0),
      veo_generation_attempt_total: Number(panel.veo_generation_attempt_total || 0),
      veo_failure_history: Array.isArray(panel.veo_failure_history) ? panel.veo_failure_history : [],
      continuity_requirements: panel.continuity_requirements || '',
    },
    binary: {
      panel_9x16: {
        data: b64,
        mimeType,
        fileName,
      },
    },
  };
});

const row = $input.first().json || {};

return [
  {
    json: {
      project_id: row.project_id || '',
      product_name: row.product_name || '',
      review_round: Number(row.review_round || 1),
      previous_review_round: Number(row.previous_review_round || 1),
      review_feedback: row.review_feedback || '',
      bad_shot_ids: row.bad_shot_ids || '',
      bad_shot_ids_list: Array.isArray(row.bad_shot_ids_list) ? row.bad_shot_ids_list : [],
      manual_regeneration_requested: true,
      review_progress_path: row.review_progress_path || '',
    },
  },
];

const items = $input.all();

return items.map((item) => {
  const json = item.json || {};
  const binary = item.binary || {};
  const panel = binary.panel_9x16 || {};
  const imageBase64 = panel.data || '';
  const mimeType = panel.mimeType || json.panel_mime_type || 'image/jpeg';

  if (!imageBase64) {
    throw new Error('ModelHub图片准备：缺少 panel_9x16 二进制图片，shot_id=' + (json.shot_id || ''));
  }

  return {
    json: {
      ...json,
      scene_image_mime_type: mimeType,
      video_provider: 'modelhub',
      video_model: 'veo3.1-fast',
      modelhub_submit_url: 'https://api.modelhub.me/v1/videos',
      modelhub_result_url_template: 'https://api.modelhub.me/v1/videos/{request_id}',
      modelhub_aspect_ratio: '9:16',
      modelhub_enhance_prompt: true,
      poll_wait_seconds: 20,
      max_poll_attempts: 60,
      poll_attempt: 0,
    },
    binary,
  };
});

const fs = require('fs');
const path = require('path');

const items = $input.all();
const out = [];

for (const item of items) {
  const json = item.json || {};
  const imagePath = String(json.panel_image_path || '').trim();
  const binary = item.binary || {};
  const panel = binary.panel_9x16 || {};
  let imageBase64 = panel.data || '';
  let mimeType = panel.mimeType || json.scene_image_mime_type || json.panel_mime_type || 'image/jpeg';

  if (!imagePath || !fs.existsSync(imagePath)) {
    throw new Error('ModelHub请求体组装：panel_image_path 不存在，shot_id=' + (json.shot_id || '') + '，path=' + imagePath);
  }
  if (!imageBase64) {
    imageBase64 = fs.readFileSync(imagePath).toString('base64');
    const ext = path.extname(imagePath).toLowerCase();
    if (!panel.mimeType && !json.scene_image_mime_type && !json.panel_mime_type) {
      mimeType = ext === '.png' ? 'image/png' : ext === '.webp' ? 'image/webp' : 'image/jpeg';
    }
  }

  const prompt = String(json.video_prompt || json.veo_prompt || '').trim();
  if (!prompt) {
    throw new Error('ModelHub请求体组装：缺少 video_prompt，shot_id=' + (json.shot_id || ''));
  }

  out.push({
    json: {
      ...json,
      video_provider: 'modelhub',
      video_model: json.video_model || 'veo3.1-fast',
      modelhub_submit_url: json.modelhub_submit_url || 'https://api.modelhub.me/v1/videos',
      modelhub_result_url_template: json.modelhub_result_url_template || 'https://api.modelhub.me/v1/videos/{request_id}',
      modelhub_aspect_ratio: json.modelhub_aspect_ratio || '9:16',
      modelhub_enhance_prompt: json.modelhub_enhance_prompt !== false,
      modelhub_image_source: 'panel_9x16_binary_from_' + imagePath,
      modelhub_request_preview: {
        model: json.video_model || 'veo3.1-fast',
        aspect_ratio: json.modelhub_aspect_ratio || '9:16',
        enhance_prompt: json.modelhub_enhance_prompt !== false,
        images_count: 1,
        image_mime_type: mimeType,
        prompt_chars: prompt.length,
      },
      poll_wait_seconds: Number(json.poll_wait_seconds || 20),
      max_poll_attempts: Number(json.max_poll_attempts || 60),
      poll_attempt: 0,
      request_id: '',
      result_get_url: '',
      veo_operation_name: '',
      veo_submit_response: {},
      modelhub_submit_response: {},
      submit_status: '',
      veo_status_response: {},
      modelhub_status: '',
      wavespeed_status: '',
      veo_done: false,
      veo_video_uri: '',
      modelhub_timeout: false,
      modelhub_failed: false,
      wavespeed_timeout: false,
      wavespeed_failed: false,
      veo_failure_reason: '',
      veo_video_failed: false,
      scene_image_url: '',
      data: undefined,
      code: undefined,
      message: undefined,
    },
    binary,
  });
}

return out;

const fs = require('fs');
const { execFileSync } = require('child_process');

function getModelHubApiKey() {
  let key = '';
  try {
    key = String(fs.readFileSync(require('path').join(require('os').homedir(), '.n8n', 'modelhub-api-key'), 'utf8') || '').trim();
  } catch (error) {}
  if (!key) {
    try {
      const env = require('process').env || {};
      key = String(env.MODELHUB_API_KEY || '').trim();
    } catch (error) {}
  }
  if (!key) {
    throw new Error('缺少 ModelHub API Key。请把 key 写入 ~/.n8n/modelhub-api-key，或设置 MODELHUB_API_KEY 环境变量。');
  }
  return key;
}

function runCurl(args, label) {
  let lastError = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return execFileSync('curl', ['-sS', '--connect-timeout', '30', '--max-time', '300', '--retry', '1', '--retry-delay', '3', ...args], { encoding: 'utf8' });
    } catch (error) {
      lastError = error;
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, attempt * 2000);
    }
  }
  throw new Error(label + ' 连续重试失败：' + String(lastError?.stderr || lastError?.message || lastError || '').slice(0, 800));
}

function parseJson(output, label) {
  const text = String(output || '').trim();
  try {
    return JSON.parse(text || '{}');
  } catch (firstError) {
    const objects = [];
    let depth = 0;
    let start = -1;
    let inString = false;
    let escape = false;
    for (let i = 0; i < text.length; i++) {
      const ch = text[i];
      if (inString) {
        if (escape) escape = false;
        else if (ch === '\\') escape = true;
        else if (ch === '"') inString = false;
        continue;
      }
      if (ch === '"') {
        inString = true;
        continue;
      }
      if (ch === '{') {
        if (depth === 0) start = i;
        depth++;
      } else if (ch === '}') {
        depth--;
        if (depth === 0 && start >= 0) {
          const candidate = text.slice(start, i + 1);
          try { objects.push(JSON.parse(candidate)); } catch (error) {}
          start = -1;
        }
      }
    }
    if (objects.length) return objects[objects.length - 1];
    throw new Error(label + ' 返回不是合法 JSON：' + firstError.message + '，body=' + text.slice(0, 500));
  }
}

const key = getModelHubApiKey();
const items = $input.all();
const out = [];

for (const item of items) {
  const json = item.json || {};
  const binary = item.binary || {};
  const panel = binary.panel_9x16 || {};
  let imageBase64 = panel.data || '';
  let mimeType = panel.mimeType || json.scene_image_mime_type || json.panel_mime_type || 'image/jpeg';
  const prompt = String(json.video_prompt || json.veo_prompt || '').trim();

  if (!imageBase64) {
    const imagePath = String(json.panel_image_path || '').trim();
    if (!imagePath || !fs.existsSync(imagePath)) throw new Error('ModelHub提交：缺少 panel_9x16 二进制图片，且 panel_image_path 不存在，shot_id=' + (json.shot_id || ''));
    imageBase64 = fs.readFileSync(imagePath).toString('base64');
    const ext = require('path').extname(imagePath).toLowerCase();
    if (!panel.mimeType && !json.scene_image_mime_type && !json.panel_mime_type) {
      mimeType = ext === '.png' ? 'image/png' : ext === '.webp' ? 'image/webp' : 'image/jpeg';
    }
  }
  if (!prompt) throw new Error('ModelHub提交：缺少 video_prompt，shot_id=' + (json.shot_id || ''));

  const body = {
    prompt: prompt.slice(0, 4000),
    model: json.video_model || 'veo3.1-fast',
    enhance_prompt: json.modelhub_enhance_prompt !== false,
    images: ['data:' + mimeType + ';base64,' + imageBase64],
    aspect_ratio: json.modelhub_aspect_ratio || '9:16',
  };

  const output = runCurl([
    '--location',
    '--request', 'POST',
    json.modelhub_submit_url || 'https://api.modelhub.me/v1/videos',
    '--header', 'Authorization: Bearer ' + key,
    '--header', 'Content-Type: application/json',
    '--data-raw', JSON.stringify(body),
  ], 'ModelHub视频提交');

  const parsed = parseJson(output, 'ModelHub视频提交');
  out.push({
    json: {
      ...json,
      modelhub_submit_response: parsed,
      veo_submit_response: parsed,
      submit_status: String(parsed.status || parsed?.data?.status || parsed?.state || '').trim(),
      modelhub_request_preview: {
        ...(json.modelhub_request_preview || {}),
        submitted_at: new Date().toISOString(),
      },
      data: parsed.data,
      code: parsed.code,
      message: parsed.message,
    },
    binary,
  });
}

return out;

const items = $input.all();

function firstString(...values) {
  for (const value of values) {
    if (value == null) continue;
    const s = String(value).trim();
    if (s) return s;
  }
  return '';
}

function findVideoUrl(value, depth = 0, seen = new Set()) {
  if (!value || depth > 8) return '';
  if (typeof value === 'string') {
