function getModelHubApiKey() {
  let key = '';
  try {
    key = String(fs.readFileSync(require('path').join(require('os').homedir(), '.n8n', 'modelhub-api-key'), 'utf8') || '').trim();
  } catch (error) {}
  if (!key) {
    try {
      const env = require('process').env || {};
      key = String(env.MODELHUB_API_KEY || '').trim();
    } catch (error) {}
  }
  if (!key) {
    throw new Error('缺少 ModelHub API Key。请把 key 写入 ~/.n8n/modelhub-api-key，或设置 MODELHUB_API_KEY 环境变量。');
  }
  return key;
}

function runCurl(args, label) {
  let lastError = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      return execFileSync('curl', ['-sS', '--connect-timeout', '30', '--max-time', '180', '--retry', '1', '--retry-delay', '3', ...args], { encoding: 'utf8' });
    } catch (error) {
      lastError = error;
      Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, attempt * 2000);
    }
  }
  throw new Error(label + ' 连续重试失败：' + String(lastError?.stderr || lastError?.message || lastError || '').slice(0, 800));
}

function parseJson(output, label) {
  const text = String(output || '').trim();
  try {
    return JSON.parse(text || '{}');
  } catch (firstError) {
    const objects = [];
    let depth = 0;
    let start = -1;
    let inString = false;
    let escape = false;
    for (let i = 0; i < text.length; i++) {
      const ch = text[i];
      if (inString) {
        if (escape) escape = false;
        else if (ch === '\\') escape = true;
        else if (ch === '"') inString = false;
        continue;
      }
      if (ch === '"') {
        inString = true;
        continue;
      }
      if (ch === '{') {
        if (depth === 0) start = i;
        depth++;
      } else if (ch === '}') {
        depth--;
        if (depth === 0 && start >= 0) {
          const candidate = text.slice(start, i + 1);
          try { objects.push(JSON.parse(candidate)); } catch (error) {}
          start = -1;
        }
      }
    }
    if (objects.length) return objects[objects.length - 1];
    throw new Error(label + ' 返回不是合法 JSON：' + firstError.message + '，body=' + text.slice(0, 500));
  }
}

