  }
  return '';
}

function findVideoUrl(value, depth = 0, seen = new Set()) {
  if (!value || depth > 8) return '';
  if (typeof value === 'string') {
    return /^https?:\/\//i.test(value) && (/\.(mp4|mov|webm)(\?|#|$)/i.test(value) || /video|output|download|oss|aliyuncs/i.test(value)) ? value : '';
  }
  if (typeof value !== 'object') return '';
  if (seen.has(value)) return '';
  seen.add(value);
  if (Array.isArray(value)) {
    for (const entry of value) {
      const found = findVideoUrl(entry, depth + 1, seen);
      if (found) return found;
    }
    return '';
  }
  for (const key of ['video_url', 'videoUrl', 'download_url', 'downloadUrl', 'output_url', 'outputUrl', 'url']) {
    const found = findVideoUrl(value[key], depth + 1, seen);
    if (found) return found;
  }
  for (const key of ['videos', 'outputs', 'output', 'result', 'data', 'metadata']) {
    const found = findVideoUrl(value[key], depth + 1, seen);
    if (found) return found;
  }
  for (const entry of Object.values(value)) {
    const found = findVideoUrl(entry, depth + 1, seen);
    if (found) return found;
  }
