}

function normalizeStatus(status, hasVideo) {
  const s = String(status || '').trim().toLowerCase();
  if (hasVideo) return 'completed';
  if (['completed', 'complete', 'succeeded', 'success', 'done', 'finished'].includes(s)) return 'completed';
  if (['failed', 'failure', 'error', 'errored', 'cancelled', 'canceled'].includes(s)) return 'failed';
  if (['queued', 'pending', 'running', 'processing', 'submitted', 'created', 'in_progress'].includes(s)) return s || 'running';
  return s || 'running';
}

