function run(cmd, args) {
  return execFileSync(cmd, args, { stdio: ['ignore', 'pipe', 'pipe'] });
}

function resolveHostWithPublicDns(hostname) {
  const servers = ['1.1.1.1', '8.8.8.8'];
  for (const server of servers) {
    try {
      const stdout = execFileSync('dig', ['@' + server, '+short', hostname], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
      const ip = stdout.split(/\r?\n/).map(l => l.trim()).find(l => /^\d+\.\d+\.\d+\.\d+$/.test(l) && !l.startsWith('127.'));
      if (ip) return ip;
    } catch (e) {}
  }
  return '';
}

function saveRemoteFile(url, targetPath) {
  const parsed = new URL(url);
  const host = parsed.hostname;
  const baseArgs = ['-L', '-sS', '--connect-timeout', '12', '--max-time', '120', '--retry', '1', '--retry-delay', '2'];
  const attempts = [];
  const publicIp = resolveHostWithPublicDns(host);
  if (publicIp) {
    attempts.push([...baseArgs, '--resolve', host + ':443:' + publicIp, url, '-o', targetPath]);
  }
  attempts.push([...baseArgs, url, '-o', targetPath]);
  let lastError = null;
  for (const args of attempts) {
    try {
      run('curl', args);
      if (fs.existsSync(targetPath) && fs.statSync(targetPath).size > 0) return;
      lastError = new Error('curl 下载完成但文件为空');
    } catch (e) {
      lastError = e;
    }
  }
  throw new Error('视频下载失败：' + String(lastError?.stderr || lastError?.message || lastError || '').slice(0, 1000));
}

