return [item];

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const base = $('审核进度初始化').first().json || $('解析用户确认').first().json || {};
const progressPath = String(base.review_progress_path || '').trim();
const projectId = String(base.project_id || 'proj').trim();
const videoDir = require('path').join(require('os').homedir(), 'Downloads', 'n8n视频');
const concatDir = require('path').join(require('path').join(require('os').homedir(), 'Downloads', 'tiktok-n8n-workflow-pack'), '.n8n-local-cache', 'final-video');
fs.mkdirSync(concatDir, { recursive: true });

let progress = {};
if (progressPath && fs.existsSync(progressPath)) {
  progress = JSON.parse(fs.readFileSync(progressPath, 'utf8'));
}

const shots = Array.isArray(progress.shots) ? progress.shots : [];
const allVideoFiles = fs.existsSync(videoDir)
  ? fs.readdirSync(videoDir)
      .filter((name) => name.endsWith('.mp4') && (name.startsWith('modelhub_' + projectId + '_') || name.startsWith('wavespeed_' + projectId + '_')))
      .map((name) => path.join(videoDir, name))
      .sort((a, b) => fs.statSync(a).mtimeMs - fs.statSync(b).mtimeMs)
  : [];

const fileByShot = new Map();
for (const filePath of allVideoFiles) {
  const baseName = path.basename(filePath);
  const prefixes = ['modelhub_' + projectId + '_', 'wavespeed_' + projectId + '_'];
  const prefix = prefixes.find((p) => baseName.startsWith(p));
  if (!prefix) continue;
  const rest = baseName.slice(prefix.length);
  const match = rest.match(/^(?:shot_)?(\d+)_/);
  if (match) fileByShot.set(String(Number(match[1])), filePath);
}

const nowIso = new Date().toISOString();
const mergedShots = shots.map((shot) => {
  const orderKey = String(Number(shot.shot_order || shot.shot_id || 0));
  const existingVideoPath = String(shot.video_path || '').trim();
  const detectedVideoPath = fileByShot.get(orderKey) || '';
  const videoPath = existingVideoPath && fs.existsSync(existingVideoPath) ? existingVideoPath : detectedVideoPath;
  if (videoPath && fs.existsSync(videoPath)) {
    return {
      ...shot,
      status: 'completed',
      video_path: videoPath,
      error: '',
      completed_at: shot.completed_at || nowIso,
    };
  }
  if (shot.status === 'running' || shot.status === 'submitted') {
    return { ...shot, status: 'pending' };
  }
  return shot;
});

const completedShots = mergedShots
  .filter((shot) => shot.status === 'completed')
  .sort((a, b) => Number(a.shot_order || 0) - Number(b.shot_order || 0));
const failedShots = mergedShots
  .filter((shot) => shot.status === 'failed')
  .map((shot) => ({
    shot_id: shot.shot_id,
    shot_order: shot.shot_order,
    operation_name: shot.operation_name || '',
    error: shot.error || '',
  }));

const completedCount = completedShots.length;
const failedCount = failedShots.length;
const runningCount = mergedShots.filter((shot) => shot.status === 'running' || shot.status === 'submitted').length;
const totalPanels = Number(progress.total_panels || base.total_panels || mergedShots.length || 0);
const rerunFailedOnly = Boolean(progress.rerun_failed_only || base.rerun_failed_only);

let status = 'running';
if (completedCount >= totalPanels && totalPanels > 0) {
  status = 'success';
} else if (rerunFailedOnly && runningCount === 0 && failedCount === 0 && completedCount > 0) {
  status = 'rerun_success';
} else if (runningCount === 0 && failedCount > 0 && completedCount > 0) {
  status = 'partial_success';
} else if (runningCount === 0 && failedCount > 0) {
  status = 'failed';
} else if (runningCount === 0 && completedCount > 0) {
  status = 'partial_success';
}

const failureReasonsSummary = failedShots.map((shot) => String(shot.shot_id) + ': ' + shot.error).join(' | ');
let finalMergedVideoPath = String(progress.final_merged_video_path || '').trim();
let finalMergedVideoName = String(progress.final_merged_video_name || '').trim();
const finalSourceSignature = completedShots.map((shot) => String(shot.video_path || '')).filter(Boolean).join('|');

if (status === 'success' && completedShots.length === totalPanels && totalPanels > 0) {
  // E-fix: skip ffmpeg only when the canonical final matches the current shot video set.
  // A stale final from an invalidated/rerun shot must not be reused.
  const existingFinalSourceSignature = String(progress.final_source_signature || '').trim();
  const canReuseCanonicalFinal = Boolean(
    finalMergedVideoPath &&
    fs.existsSync(finalMergedVideoPath) &&
    fs.statSync(finalMergedVideoPath).size > 0 &&
    existingFinalSourceSignature &&
    existingFinalSourceSignature === finalSourceSignature
  );
  if (canReuseCanonicalFinal) {
    finalMergedVideoName = path.basename(finalMergedVideoPath);
  } else {
  try {
    const listPath = path.join(concatDir, 'concat_' + projectId + '.txt');
    const mergedName = 'final_' + projectId + '_' + Date.now() + '.mp4';
    const mergedPath = path.join(videoDir, mergedName);
    const lines = completedShots.map((shot) => "file '" + String(shot.video_path || '').replace(/'/g, "'\\''") + "'");
    fs.writeFileSync(listPath, lines.join('\n') + '\n');
    execFileSync('ffmpeg', ['-y', '-f', 'concat', '-safe', '0', '-i', listPath, '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '20', '-c:a', 'aac', '-movflags', '+faststart', mergedPath], { stdio: ['ignore', 'pipe', 'pipe'] });
    if (fs.existsSync(mergedPath) && fs.statSync(mergedPath).size > 0) {
      finalMergedVideoPath = mergedPath;
      finalMergedVideoName = mergedName;
    }
  } catch (error) {
    status = 'partial_success';
    progress.final_merge_error = error.message;
  }
  }
}

const nextProgress = {
  ...progress,
  shots: mergedShots,
  total_panels: totalPanels,
  completed_count: completedCount,
  running_count: runningCount,
  failed_count: failedCount,
  status,
  failure_reasons_summary: failureReasonsSummary,
  video_files: completedShots.map((shot) => shot.video_path).filter(Boolean),
  failed_shots: failedShots,
  final_merged_video_path: finalMergedVideoPath,
  final_merged_video_name: finalMergedVideoName,
  final_source_signature: finalMergedVideoPath ? finalSourceSignature : (progress.final_source_signature || ''),
  updated_at: nowIso,
  finished_at: runningCount === 0 ? nowIso : progress.finished_at || '',
};

if (progressPath) {
  fs.writeFileSync(progressPath, JSON.stringify(nextProgress, null, 2));
}

return [{ json: nextProgress }];

const row = $input.first().json || {};
const history = Array.isArray(row.veo_failure_history) ? row.veo_failure_history : [];

if (!row.veo_video_failed) {
  return [{
    json: {
      ...row,
      veo_recovery_action: 'success',
      veo_fail_streak: 0,
      veo_generation_attempt_total: Number(row.veo_generation_attempt_total || 0),
      veo_failure_history: history,
    },
  }];
}

const failStreak = Number(row.veo_fail_streak || 0) + 1;
const totalAttempts = Number(row.veo_generation_attempt_total || 0) + 1;
const promptRegens = Number(row.veo_prompt_regen_count || 0);
const failureEntry = {
  at: new Date().toISOString(),
  shot_id: row.shot_id || ('shot_' + (row.shot_order || 'x')),
  shot_order: row.shot_order || null,
  fail_streak: failStreak,
  total_attempt: totalAttempts,
  prompt_regen_count: promptRegens,
  operation_name: row.veo_operation_name || '',
  reason: String(row.veo_failure_reason || '').trim(),
};
let action = 'retry_same_prompt';
if (failStreak >= 3) {
  action = promptRegens < 2 ? 'regenerate_prompt' : 'give_up';
}
return [{
  json: {
    ...row,
    veo_recovery_action: action,
    veo_fail_streak: failStreak,
    veo_generation_attempt_total: totalAttempts,
    veo_last_failure_reason: failureEntry.reason,
    veo_failure_history: [...history, failureEntry],
  },
}];

const fs = require('fs');
const promptsPath = require('path').join(require('path').join(require('os').homedir(), 'Downloads', 'tiktok-n8n-workflow-pack'), 'tiktok-workflow-prompts.json');
const prompts = JSON.parse(fs.readFileSync(promptsPath, 'utf8'));
const cfg = prompts.veo_repair || {};
const row = $input.first().json || {};

function tpl(str, vars) {
  let out = String(str || '');
  for (const [k, v] of Object.entries(vars)) {
    out = out.split('{{' + k + '}}').join(v == null ? '' : String(v));
  }
  return out;
}

const history = Array.isArray(row.veo_failure_history) ? row.veo_failure_history : [];
const userText = tpl(cfg.user_template || '', {
  project_id: row.project_id || '',
  product_name: row.product_name || '',
  shot_id: row.shot_id || '',
  shot_order: row.shot_order || '',
  stage: row.stage || '',
  duration: row.duration || '',
  video_prompt: row.video_prompt || row.veo_prompt_original || '',
  failure_reason: row.veo_last_failure_reason || row.veo_failure_reason || '',
  failure_history_json: JSON.stringify(history.slice(-6), null, 2),
  continuity_requirements: row.continuity_requirements || '',
});

return [{
  json: {
    ...row,
    request_body: {
      system_instruction: { parts: [{ text: cfg.system_instruction || '' }] },
      contents: [{ role: 'user', parts: [{ text: userText }] }],
      generationConfig: cfg.generation_config || { responseMimeType: 'application/json' },
    },
  },
}];

const base = $('Veo失败提示词请求体').first().json || {};
const rawText = $input.first().json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let parsed = {};
try {
  parsed = JSON.parse(rawText);
} catch (error) {
  throw new Error('Veo失败提示词解析失败：返回内容不是合法 JSON，详情：' + error.message);
}
const nextPrompt = String(parsed.video_prompt || '').trim();
if (!nextPrompt) {
  throw new Error('Veo失败提示词解析失败：未返回 video_prompt');
}
return [{
  json: {
    ...base,
    video_prompt: nextPrompt,
    veo_prompt_regen_count: Number(base.veo_prompt_regen_count || 0) + 1,
    veo_fail_streak: 0,
    veo_recovery_action: 'retry_after_regen',
    veo_prompt_adjustment_summary: parsed.adjustment_summary || '',
    veo_prompt_risk_notes: parsed.risk_notes || '',
    veo_last_failure_reason: '',
  },
}];
